    function getStats(player) {
        var key = player.auth || player.name;
        if (!playerStats[key]) {
            playerStats[key] = {
                name: player.name,
                auth: player.auth,
                goals: 0,
                assists: 0,
                ownGoals: 0,
                wins: 0,
                losses: 0,
                matches: 0,
                mvp: 0,
                streak: 0,
                bestStreak: 0
            };
        }
        playerStats[key].name = player.name;
        return playerStats[key];
    }

    function getRank(st) {
        if (st.wins >= 50) return "🐐 [Yusuf Reis]";
        if (st.wins >= 30) return "👑 [Köfte Kralı]";
        if (st.wins >= 15) return "🔥 [Usta Köfteci]";
        if (st.wins >= 8)  return "🥩 [Kasap]";
        if (st.wins >= 3)  return "🍖 [Izgaracı]";
        return "🌱 [Çırak]";
    }

    var activeAnimTimeouts = [];
