    function addAnimTimeout(fn, delay) {
        var tid = setTimeout(fn, delay);
        activeAnimTimeouts.push(tid);
        return tid;
    }

    function addAnimInterval(fn, delay) {
        var iid = setInterval(fn, delay);
        activeAnimIntervals.push(iid);
        return iid;
    }

    function clearAllAnimations() {
        activeAnimTimeouts.forEach(clearTimeout);
        activeAnimTimeouts = [];
        activeAnimIntervals.forEach(clearInterval);
        activeAnimIntervals = [];

        try {
            var players = room.getPlayerList();
            players.forEach(function(p) {
                if (p.id !== 0) {
                    room.setPlayerAvatar(p.id, null);
                    room.setPlayerDiscProperties(p.id, { radius: 15, color: -1, damping: 0.96 });
                }
            });
            room.setDiscProperties(0, { color: 0xFFEA00, radius: 6.4 });
        } catch(e) {}
    }

    room.setScoreLimit(5);
    room.setTimeLimit(3);

    function updateStadiumByPlayerCount(targetTier) {
        if (targetTier < 1) targetTier = 1;
        if (targetTier > 5) targetTier = 5;

        if (currentMapTier !== targetTier) {
            currentMapTier = targetTier;
            var hbsMap = MAP_POOLS[targetTier];
            room.stopGame();
            room.setCustomStadium(hbsMap);
            sendAnnouncement("🏟️ Harita Değiştirildi: " + targetTier + "v" + targetTier + " Köfteci Yusuf Futsal", null, 0xFACC15, "bold", 1);
        }
    }

    function autoBalanceTeams() {
        if (isTeamsLocked) return;
        var activePlayers = room.getPlayerList().filter(p => p.id !== 0 && !afkList.has(p.id));
        var total = activePlayers.length;

        if (total === 0) {
            room.stopGame();
            gameActive = false;
            return;
        }

        if (total === 1) {
            updateStadiumByPlayerCount(1);
            room.setPlayerTeam(activePlayers[0].id, 1);
            room.stopGame();
            gameActive = false;
            sendInfo("Rakip bekleniyor... (1v1 için 1 oyuncu daha lazım)");
            return;
        }

        var targetPerTeam = Math.min(5, Math.floor(total / 2));
        updateStadiumByPlayerCount(targetPerTeam);

        var redPlayers = activePlayers.filter(p => p.team === 1);
        var bluePlayers = activePlayers.filter(p => p.team === 2);
        var specs = activePlayers.filter(p => p.team === 0);

        specs.forEach(p => {
            if (redPlayers.length < targetPerTeam) {
                room.setPlayerTeam(p.id, 1);
                redPlayers.push(p);
            } else if (bluePlayers.length < targetPerTeam) {
                room.setPlayerTeam(p.id, 2);
                bluePlayers.push(p);
            }
        });

        while (Math.abs(redPlayers.length - bluePlayers.length) > 1) {
            if (redPlayers.length > bluePlayers.length) {
                var m = redPlayers.pop();
                room.setPlayerTeam(m.id, 2);
                bluePlayers.push(m);
            } else {
                var m = bluePlayers.pop();
                room.setPlayerTeam(m.id, 1);
                redPlayers.push(m);
            }
        }

        var scores = room.getScores();
        if (!scores || !gameActive) {
            room.stopGame();
            room.startGame();
            gameActive = true;
            sendSuccess("Takımlar eşitlendi (" + redPlayers.length + "v" + bluePlayers.length + ")! Maç Başladı!");
        }
    }

